with kept as (select s.* from orders s where not exists (select 1 from order_items c where c.order_id = s.id and c.unit_price < 360)) select date_trunc('year', order_date) as year_start, size(collect_set(status)) as num_status, sum(amount) filter (where status = 'COMPLETED') as completed_total_amount, corr(discount, amount) as corr_discount_amount from kept group by date_trunc('year', order_date) having corr(discount, amount) < 1000000;
